import { SEED, playlistId, time } from './core.mjs';
const $ = id => document.getElementById(id);
const storage = {get(key, fallback) {try { return localStorage.getItem(`pocketamp:${key}`) ?? fallback; } catch {return fallback;}}, set(key,value) {try {localStorage.setItem(`pocketamp:${key}`, value);} catch {}}};
let current = SEED;
try {current = playlistId(new URL(location.href).searchParams.get('list') || storage.get('playlist', SEED));} catch {}
let player, ready = false, ids = [], lastSignature = '', selected = -1, loading = false, refreshTimer, generation = 0;
const metadata = new Map();
let shuffled = false, repeated = false;
const themes = [
  ['Original', '#b7ff55','#10120f','#1c1f1a','#b7ce91','#202d17'],
  ['After hours','#bd9bff','#121017','#201c29','#c9b8e5','#32234b'],
  ['Blue Monday','#65d9ff','#0c131b','#172330','#abd4df','#173c48'],
  ['Cherry bomb','#ff8b8b','#1a1011','#2b1c1d','#e5b7ae','#492722'],
  ['Amber radio','#ffbf55','#19140b','#2b2418','#d5c08c','#493916'],
  ['Arctic silver','#d9e7ff','#14171c','#232a34','#c5d2d7','#273e49'],
  ['Bubblegum','#ff9ddb','#1c121a','#2e202b','#e6bddb','#48223c'],
  ['Ocean drive','#5affe0','#0d1917','#192d28','#acd8c6','#19493b']
];
function skin(index) {const theme=themes[index] || themes[0]; ['--accent','--bg','--panel','--lcd','--ink'].forEach((v,i)=>document.documentElement.style.setProperty(v,theme[i+1]));storage.set('skin',index);document.querySelectorAll('.skin').forEach((b,i)=>b.setAttribute('aria-pressed',String(i===index)));}
themes.forEach((theme,index)=>{const b=document.createElement('button');b.className='skin';b.style.setProperty('--swatch',theme[1]);b.style.setProperty('--swatch-panel',theme[3]);const swatch=document.createElement('span');swatch.className='swatch';b.append(swatch,document.createTextNode(theme[0]));b.onclick=()=>skin(index);$('skin-grid').append(b);});
skin(Number(storage.get('skin','0')));
for(let i=0;i<22;i++){const bar=document.createElement('span');bar.style.setProperty('--height',`${20+((i*37)%80)}%`);bar.style.setProperty('--delay',`${-i*93}ms`);document.querySelector('.bars').append(bar);}
$('skins-open').onclick=()=>$('skins').showModal();
$('compact').onclick=()=>document.querySelector('.deck').classList.toggle('compact');
function message(text) {$('message').textContent=text;}
function updateSource() {$('playlist-name').textContent=current===SEED?'RAWM’s daily mix':'Your daily mix';$('playlist-description').textContent=current===SEED?'The actual rotation. Updated by RAWM, played by you.':'Your playlist, straight from YouTube. Make yourself at home.';$('youtube-link').href=`https://www.youtube.com/playlist?list=${encodeURIComponent(current)}`;}
updateSource();
function emptyQueue(title, detail) {const box=document.createElement('div');box.className='queue-empty';const icon=document.createElement('span');icon.className='disc';icon.textContent='◎';const h=document.createElement('h3');h.textContent=title;const p=document.createElement('p');p.textContent=detail;box.append(icon,h,p);$('queue').replaceChildren(box);}
function renderQueue() {const fragment=document.createDocumentFragment();ids.forEach((id,index)=>{const track=metadata.get(id);const b=document.createElement('button');b.className=`track${index===selected?' active':''}`;b.setAttribute('aria-current',index===selected?'true':'false');const number=document.createElement('span');number.className='track-number';number.textContent=index===selected?'▶':String(index+1).padStart(2,'0');const img=document.createElement('img');img.src=`https://i.ytimg.com/vi/${encodeURIComponent(id)}/default.jpg`;img.alt='';img.loading='lazy';const info=document.createElement('span');info.className='track-info';const title=document.createElement('span');title.className='track-title';title.textContent=track?.title || `Track ${index+1}`;const author=document.createElement('span');author.className='track-author';author.textContent=track?.author_name || 'YouTube · title available when played';info.append(title,author);b.append(number,img,info);b.onclick=()=>{if(ready)player.playVideoAt(index);};fragment.append(b);});$('queue').replaceChildren(fragment);$('queue-count').textContent=`/ ${ids.length} TRACKS`;}
async function fetchTitles(list, token) {let cursor=0;await Promise.all(Array.from({length:4},async()=>{while(cursor<list.length && token===generation){const id=list[cursor++];if(metadata.has(id))continue;try {const r=await fetch(`https://www.youtube.com/oembed?url=${encodeURIComponent(`https://www.youtube.com/watch?v=${id}`)}&format=json`,{signal:AbortSignal.timeout(6000)});if(r.ok){const data=await r.json();metadata.set(id,{title:data.title,author_name:data.author_name});if(token===generation)renderQueue();}}catch {}}}));}
function syncQueue() {if(!ready)return;const list=player.getPlaylist?.() || [];const signature=list.join(',');if(list.length && signature!==lastSignature){ids=list;lastSignature=signature;loading=false;clearTimeout(refreshTimer);selected=player.getPlaylistIndex();renderQueue();fetchTitles([...ids],generation);$('queue-note').textContent='Live playlist loaded from YouTube.';} }
function sync() {if(!ready)return;syncQueue();const data=player.getVideoData?.();if(data?.title){$('track-title').textContent=data.title;if(data.video_id && metadata.get(data.video_id)?.title!==data.title){metadata.set(data.video_id,{title:data.title,author_name:data.author});if(ids.length)renderQueue();}}const index=player.getPlaylistIndex?.();if(index!==selected){selected=index;if(ids.length)renderQueue();}const elapsed=player.getCurrentTime?.() || 0,duration=player.getDuration?.() || 0;$('clock').textContent=time(elapsed).padStart(5,'0');$('elapsed').textContent=time(elapsed);$('duration').textContent=time(duration);if(document.activeElement!==$('seek'))$('seek').value=duration?elapsed/duration*100:0;$('seek').disabled=!duration;$('track-position').textContent=ids.length?`TRACK ${Math.max(0,selected)+1} / ${ids.length}`:'YOUR MUSIC, ON REPEAT';}
function load(id, autoplay=false) {current=id;generation++;ids=[];lastSignature='';selected=-1;loading=true;updateSource();storage.set('playlist',id);const url=new URL(location.href);url.searchParams.set('list',id);history.replaceState(null,'',url);$('queue-count').textContent='/ LOADING';emptyQueue('Finding your rotation.','Loading the latest tracks directly from YouTube.');$('track-title').textContent='LOADING YOUR PLAYLIST';$('form-error').textContent='';message('Loading the latest playlist…');if(ready){player.setShuffle(false);shuffled=false;$('shuffle').setAttribute('aria-pressed','false');player[autoplay?'loadPlaylist':'cuePlaylist']({listType:'playlist',list:id,index:0});player.setLoop(repeated);}clearTimeout(refreshTimer);refreshTimer=setTimeout(()=>{if(loading){emptyQueue('Tap play to load the queue.','YouTube may reveal tracks after playback starts. If it stays empty, check that the playlist is public and allows embedding.');message('Press play, or open this playlist on YouTube if it is unavailable.');}},12000);}
window.onYouTubeIframeAPIReady=()=>{player=new YT.Player('youtube',{width:'100%',height:'236',playerVars:{listType:'playlist',list:current,playsinline:1,controls:1,origin:location.origin,rel:0},events:{onReady:()=>{ready=true;['play','previous','next','shuffle','repeat'].forEach(id=>$(id).disabled=false);player.setVolume(Number($('volume').value));$('play-status').textContent='READY';load(current);sync();setInterval(sync,750);},onStateChange:e=>{const playing=e.data===1;document.body.classList.toggle('playing',playing);$('play').textContent=playing?'Ⅱ':'▶';$('play').setAttribute('aria-label',playing?'Pause':'Play');$('play-status').textContent=({1:'PLAYING',2:'PAUSED',3:'BUFFERING',0:'ENDED',5:'READY'})[e.data] || 'READY';message(playing?'You’re listening to your rotation.':e.data===3?'Buffering…':e.data===2?'Paused. Pick up whenever.':'Hit play. Settle in.');sync();},onError:e=>{const errors={2:'YouTube could not load this playlist.',5:'Your browser could not play this video.',100:'This video was removed or is private. Try the next track.',101:'This track cannot be embedded. Try the next track or open YouTube.',150:'This track cannot be embedded. Try the next track or open YouTube.',153:'YouTube could not verify this browser. Open the playlist on YouTube.'};message(errors[e.data] || 'YouTube is unavailable. Try refreshing the playlist.');$('play-status').textContent='UNAVAILABLE';document.body.classList.remove('playing');if(!ids.length){loading=false;clearTimeout(refreshTimer);emptyQueue('YouTube cannot load this playlist.', 'This playlist or its first track may not allow embedding. Try another playlist, or listen using Open on YouTube.');$('queue-count').textContent='/ UNAVAILABLE';}},onAutoplayBlocked:()=>message('Your browser needs a tap on the YouTube play button to start.')}});};
const script=document.createElement('script');script.src='https://www.youtube.com/iframe_api';script.onerror=()=>message('YouTube could not connect. Check your connection or open the playlist on YouTube.');document.head.append(script);
setTimeout(()=>{if(!ready){$('play-status').textContent='OFFLINE';message('YouTube is taking longer than expected. Check your connection or open the playlist on YouTube.');emptyQueue('Waiting for YouTube.','Your playlist is saved. Reload when your connection is back.');}},18000);
function playPause(){if(ready){player.getPlayerState()===1?player.pauseVideo():player.playVideo();}}
$('play').onclick=playPause;$('previous').onclick=()=>player.previousVideo();$('next').onclick=()=>player.nextVideo();
$('seek').oninput=()=>{if(ready)player.seekTo(Number($('seek').value)/100*player.getDuration(),true);};
$('volume').value=Math.min(100,Math.max(0,Number(storage.get('volume','75')) || 0));$('volume-value').textContent=`${$('volume').value}%`;
$('volume').oninput=()=>{storage.set('volume',$('volume').value);$('volume-value').textContent=`${$('volume').value}%`;if(ready)player.setVolume(Number($('volume').value));};
$('shuffle').onclick=()=>{shuffled=!shuffled;player.setShuffle(shuffled);$('shuffle').setAttribute('aria-pressed',String(shuffled));syncQueue();};
$('repeat').onclick=()=>{repeated=!repeated;player.setLoop(repeated);$('repeat').setAttribute('aria-pressed',String(repeated));};
$('playlist-form').onsubmit=e=>{e.preventDefault();try {load(playlistId($('playlist-url').value),true);$('playlist-url').value='';}catch(error){$('form-error').textContent=error.message;}};
$('home-mix').onclick=()=>load(SEED,true);$('refresh').onclick=()=>load(current,false);
document.addEventListener('keydown',e=>{if(e.target.closest('input,textarea,select,button') || $('skins').open || e.ctrlKey || e.metaKey || e.altKey)return;const key=e.key.toLowerCase();if([' ','z','x','c','v','b','l'].includes(key))e.preventDefault();if(key==='l'){$('playlist-url').focus();return;}if(!ready)return;if(key===' ')playPause();if(key==='z')player.previousVideo();if(key==='b')player.nextVideo();if(key==='x')player.playVideo();if(key==='c')player.pauseVideo();if(key==='v')player.stopVideo();});
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'get_playlist_state',description:'Read the currently selected Pocket Amp playlist and playback state.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute:()=>({playlistId:current,ready,trackCount:ids.length,trackIndex:selected,playing:ready && player.getPlayerState()===1})})).catch(()=>{});}catch{}}